public static boolean containsEven(List<Object> nestedInt) {
    for (Object obj : nestedInt) {
        if (obj instanceof Integer) {
            if ((int) obj % 2 == 0) {
                return true;
            }
        } else if (obj instanceof List) {
            if (containsEven((List<Object>) obj)) {
                return true;
            }
        }
    }
    return false;
}
```

