        int arr[] = {4, 3, 6, 2, 5, 1};

        System.out.println("Original array: " + Arrays.toString(arr));

        quickSortIterative(arr, 0, arr.length - 1);

        System.out.println("Sorted array in descending order: " + Arrays.toString(arr));
    }

    public static void quickSortIterative(int arr[], int low, int high) {
        // Create a stack to store the indices of subarrays
        Stack<Integer> stack = new Stack<>();

        // Push initial values of low and high to the stack
        stack.push(low);
        stack.push(high);

        // Iterate until the stack is empty
        while (!stack.isEmpty()) {
            // Pop high and low values from the stack
            high = stack.pop();
            low = stack.pop();

            // Set pivot element as the last element of the subarray
            int pivot = arr[high];

            // Set the index of the smaller element
            int i = (low - 1);

            // Partition the array and move elements smaller than the pivot to the left side
            for (int j = low; j < high; j++) {
                if (arr[j] >= pivot) {
                    i++;

                    // Swap arr[i] and arr[j]
                    int temp = arr[i];
                    arr[i] = arr[j];
                    arr[j] = temp;
                }
            }

            // Swap arr[i+1] and arr[high] (or pivot)
            int temp = arr[i + 1];
            arr[i + 1] = arr[high];
            arr[high] = temp;

            // If there are elements on the left side of the pivot, push their indices to the stack
            if (i - low > 1) {
                stack.push(low);
                stack.push(i - 1);
            }

            // If there are elements on the right side of the pivot, push their indices to the stack
            if (high - i > 1) {
                stack.push(i + 1);
                stack.push(high);
            }
        }
    }
}"}]

