    int num = 0;
    int sign = 1;
    int i = 0;

    // Check for negative sign
    if (str.charAt(i) == '-') {
        sign = -1;
        i++;
    }

    // Process each character of the string
    while (i < str.length()) {
        char c = str.charAt(i);

        // Check if character is a digit
        if (c >= '0' && c <= '9') {
            int digit = c - '0';

            // Check for overflow
            if (num > Integer.MAX_VALUE / 10 || (num == Integer.MAX_VALUE / 10 && digit > 7)) {
                return 0;
            }

            num = num * 10 + digit;
        } else {
            // Return 0 if any non-digit character is found
            return 0;
        }

        i++;
    }

    return sign * num;
}
```

