[{"role": "assistant", "content": "Here is a possible implementation of the function that sorts the list in ascending order without using any built-in sorting methods or libraries, while maintaining the relative order of duplicate numbers:

```java
import java.util.ArrayList;
import java.util.List;

public class SortingAlgorithm {

    public static List<Integer> sortList(List<Integer> nums) {
        if (nums == null || nums.size() <= 1) {
            return nums;
        }

        // Create a new list to store the sorted result
        List<Integer> sortedList = new ArrayList<>(nums);

        mergeSort(sortedList, 0, sortedList.size() - 1);

        return sortedList;
    }

    private static void mergeSort(List<Integer> nums, int left, int right) {
        if (left < right) {
            int mid = (left + right) / 2;

            // Recursive calls to divide the list into smaller sublists
            mergeSort(nums, left, mid);
            mergeSort(nums, mid + 1, right);

            merge(nums, left, mid, right);
        }
    }

    private static void merge(List<Integer> nums, int left, int mid, int right) {
        int n1 = mid - left + 1;
        int n2 = right - mid;

        List<Integer> leftList = new ArrayList<>();
        List<Integer> rightList = new ArrayList<>();

        for (int i = 0; i < n1; i++) {
            leftList.add(nums.get(left + i));
        }

        for (int j = 0; j < n2; j++) {
            rightList.add(nums.get(mid + 1 + j));
        }

        int i = 0, j = 0;
        int k = left;

        while (i < n1 && j < n2) {
            if (leftList.get(i) <= rightList.get(j)) {
                nums.set(k, leftList.get(i));
                i++;
            } else {
                nums.set(k, rightList.get(j));
                j++;
            }
            k++;
        }

        while (i < n1) {
            nums.set(k, leftList.get(i));
            i++;
            k++;
        }

        while (j < n2) {
            nums.set(k, rightList.get(j));
            j++;
            k++;
        }
    }

    public static void main(String[] args) {
        List<Integer> nums = new ArrayList<>();
        nums.add(10);
        nums.add(2);
        nums.add(9);
        nums.add(6);

        List<Integer> sortedList = sortList(nums);

        System.out.println(sortedList);  // Output: [2, 6, 9, 10]
    }
}
```

The above implementation uses the merge sort algorithm, which has a time complexity of O(nlogn) and is space efficient with O(1) extra space."}]

