import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class SegmentedSieve {

    public static int[] segmentedSieve(int number) {
        if (number < 2) {
            return new int[0];
        }

        boolean[] sieve = new boolean[number + 1];
        Arrays.fill(sieve, true);

        for (int p = 2; p * p <= number; p++) {
            if (sieve[p]) {
                for (int i = p * p; i <= number; i += p) {
                    sieve[i] = false;
                }
            }
        }

        List<Integer> primes = new ArrayList<>();
        for (int p = 2; p <= number; p++) {
            if (sieve[p]) {
                primes.add(p);
            }
        }

        return primes.stream().mapToInt(Integer::intValue).toArray();
    }

    public static void main(String[] args) {
        int number = 20;
        int[] primes = segmentedSieve(number);
        System.out.println("Prime numbers from 2 to " + number + ": " + Arrays.toString(primes));
    }
}
```

