public class ArrayFilter {
    public static int[] filterArray(int[] arr, int num) {
        // Filter the array
        int count = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] >= num) {
                arr[count++] = arr[i];
            }
        }

        // Create a new array with the filtered elements
        int[] filteredArr = Arrays.copyOf(arr, count);

        // Sort the new array in ascending order
        Arrays.sort(filteredArr);

