public class RecursiveAlgorithm {
    public static int recursive(int n) {
        // Base case: if n is 2 or less, return n if it's even, otherwise return 0
        if (n <= 2) {
            if (n % 2 == 0) {
                return n;
            } else {
                return 0;
            }
        }

        // Recursive case: if n is positive, return the sum of n and recursive(n-2)
        if (n > 0) {
            return n + recursive(n - 2);
        }

        // Recursive case: if n is negative, return the sum of n and recursive(n+2)
        return n + recursive(n + 2);
    }

    public static void main(String[] args) {
        int n = 10;
        int sum = recursive(n);
        System.out.println("Sum of even numbers from 2 to " + n + " is: " + sum);
    }
}
