public static void printUniqueElementsInReverse(int[] arr) {
    int n = arr.length;

    // Loop through the array from the last element to the first element
    for (int i = n - 1; i >= 0; i--) {
        boolean isUnique = true;

        // Check if the current element is unique by comparing it with all the elements before it
        for (int j = i - 1; j >= 0; j--) {
            if (arr[i] == arr[j]) {
                isUnique = false;
                break;
            }
        }

        // If the element is unique, print it
        if (isUnique) {
            System.out.println(arr[i]);
        }
    }
}
