public class InPlaceInsertionSort {
    public static int[] sortAndRemoveDuplicates(int[] arr) {
        if (arr == null || arr.length <= 1) {
            return arr;
        }

        int n = arr.length;
        for (int i = 1; i < n; i++) {
            int key = arr[i];
            int j = i - 1;

            while (j >= 0 && arr[j] > key) {
                arr[j + 1] = arr[j];
                j--;
            }

            arr[j + 1] = key;
        }

        int[] result = new int[n];
        result[0] = arr[0];
        int k = 1;

        for (int i = 1; i < n; i++) {
            if (arr[i] != arr[i - 1]) {
                result[k] = arr[i];
                k++;
            }
        }

        return Arrays.copyOf(result, k);
    }

    public static void main(String[] args) {
        int[] arr = {4, 2, 6, 3, 2, 8, 4};
        int[] sortedArr = sortAndRemoveDuplicates(arr);

        System.out.println(Arrays.toString(sortedArr));
    }
}
