        if (!isPrime(length) || !isPrime(breadth) || length > 1000 || breadth > 1000) {
            throw new InvalidDimensionException("Invalid dimensions! Length and breadth must be prime numbers and not exceed 1000.");
        }
        this.length = length;
        this.breadth = breadth;
    }

