public class Solution {
    private static final ExecutorService executor = Executors.newCachedThreadPool();

    public static List<Integer> uncommonSortList(List<Integer> lst) throws InterruptedException, ExecutionException {
        List<Integer> result = new ArrayList<>();
        int size = lst.size();
        if (size == 0)
            return result;

        List<Integer> temp = new ArrayList<>(lst);
        boolean flag = true;
        while(result.size() < size){
            if(flag){
                Future<Integer> minFuture = executor.submit(() -> Collections.min(temp));
                Integer min = minFuture.get();
                result.add(min);
                temp.remove(min);
            }else{
                Future<Integer> maxFuture = executor.submit(() -> Collections.max(temp));
                Integer max = maxFuture.get();
                result.add(max);
                temp.remove(max);
            }

            flag = !flag;
        }
        executor.shutdown();
        return result;
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        List<Integer> list1 = Arrays.asList(1, 2, 3, 4);
        List<Integer> list2 = Arrays.asList(5, 5, 5, 5);

        System.out.println(uncommonSortList(list1)); //[1, 4, 2, 3]
        System.out.println(uncommonSortList(list2)); //[5, 5, 5, 5]
    }
}
```

