import java.util.*;

class Permutation {
    String str;
    ArrayList<String> permutations = new ArrayList<>();

    Permutation(String str) {
        this.str = str;
    }

    synchronized void permutation(String prefix, String str) {
        int n = str.length();
        if (n == 0) this.permutations.add(prefix);
        else {
            for (int i = 0; i < n; i++)
                permutation(prefix + str.charAt(i), str.substring(0, i) + str.substring(i + 1, n));
        }
    }

    void display() {
        for (String perm : permutations) {
            System.out.println(perm);
        }
    }
}

class PermutationThread extends Thread {
    Permutation p;
    String prefix, str;

    PermutationThread(Permutation p, String prefix, String str) {
        this.p = p;
        this.prefix = prefix;
        this.str = str;
    }

    @Override
    public void run() {
        p.permutation(prefix, str);
    }
}

public class Main {
    public static void main(String[] args) {
        Permutation p = new Permutation("hello world");
        new PermutationThread(p, "", "hello world").start();

        // Ensure concurrency safety by utilizing the synchronized block
        synchronized(p) {
            p.display();
        }
    }
}
```
This program initializes an instance of the `Permutation` class with the string "hello world", spawns a new thread that generates all permutations of the string, and then prints those permutations. Note that the `Permutation.permutation` method is synchronized to ensure that no two threads can invoke this method on the same `Permutation` object at the same time.
