```Java
import java.util.*;

public class Anagram {

    public static Map<String, List<String>> findAnagrams(String[] lexemes) {
        Map<String, List<String>> anagramsMap = new HashMap<>();
        for (String lexeme : lexemes) {
            if (lexeme.length() >= 2) {
                char[] characters = lexeme.toCharArray();  
                Arrays.sort(characters);  
                String sorted = new String(characters);  

                if (anagramsMap.containsKey(sorted)) {
                    anagramsMap.get(sorted).add(lexeme);
                } else {
                    List<String> anagramsList = new ArrayList<>();
                    anagramsList.add(lexeme);
                    anagramsMap.put(sorted, anagramsList);
                }
            }
        }

        return anagramsMap;
    }

    public static void main(String[] args) {
        String[] lexemes = {"cat", "dog", "tac", "god", "good", "act"};
        Map<String, List<String>> anagrams = findAnagrams(lexemes);
        for (Map.Entry<String, List<String>> entry : anagrams.entrySet()) {
            if (entry.getValue().size() > 1) {
                System.out.println("Lexeme : " +entry.getKey()+" , Anagrams : " +entry.getValue());
            }
        }
    }
}
