public static int[] countAndSort(int[] arr, int threshold) throws Exception {
    if (arr == null || arr.length == 0) {
        throw new Exception("Input array is empty");
    }

    // Clone the array to sort so we don't lose original positions
    int[] clonedArr = arr.clone();
    int count = 0;

    // Implement bubble sort for descending order
    for (int i = 0; i < clonedArr.length; i++) {
        if (clonedArr[i] > threshold) {
            for (int j = i + 1; j < clonedArr.length; j++) {
                if (clonedArr[j] > clonedArr[i]) {
                    int temp = clonedArr[i];
                    clonedArr[i] = clonedArr[j];
                    clonedArr[j] = temp;
                }
            }
            count++;
        }
    }

    // Create new array for the result
    int[] result = new int[count];
    int index = 0;

    // Print original positions and fill result array
    for (int i = 0; i < clonedArr.length; i++) {
        if (clonedArr[i] > threshold) {
            result[index] = clonedArr[i];
            System.out.println("Number " + clonedArr[i] + " at position " + i);
            index++;
        }
    }

    // Return result array
    return result;
}
```
