import java.util.*;

public class Main {
    public static void main(String[] args) {
        final int MAX_RANGE = 1000000;

        // Using the Sieve of Eratosthenes algorithm to find all primes up to n
        boolean[] primes = new boolean[MAX_RANGE + 1];
        for(int i = 0; i < primes.length; i++) primes[i] = true; 
        for(int p = 2; p * p <= MAX_RANGE; p++) {
            if(primes[p]) {
                for(int i = p * p; i <= MAX_RANGE; i += p) primes[i] = false;
            }
        }

        // Use an array to count digit appearances in primes
        int[] digitCounts = new int[10];
        PriorityQueue<Integer> primeQueue = new PriorityQueue<>();
        for(int i = 2; i <= MAX_RANGE; i++) {
            if(primes[i]) {
                primeQueue.offer(i);
                char[] digits = Integer.toString(i).toCharArray();
                for(char digit : digits) {
                    digitCounts[Character.getNumericValue(digit)]++;
                }
            }
        }

        // Display the sorted prime numbers
        while(!primeQueue.isEmpty()) {
            System.out.println(primeQueue.poll());
        }

        // Find and display the most common digit
        int maxIndex = 0;
        for(int i = 0; i < digitCounts.length; i++) {
            if(digitCounts[i] > digitCounts[maxIndex]) {
                maxIndex = i;
            }
        }
        System.out.println("The most frequently appearing digit in all primes in this set is " +
                            maxIndex + " with a count of " + digitCounts[maxIndex] + ".");
    }
}
