import java.util.PriorityQueue;
import java.util.Comparator;

public class MedianHeap {
    // Max heap for the lower half of numbers
    private PriorityQueue<Integer> maxHeap;
    // Min heap for the upper half of numbers
    private PriorityQueue<Integer> minHeap;

    public MedianHeap() {
        maxHeap = new PriorityQueue<>(Comparator.reverseOrder()); // reverseOrder to make it a max heap
        minHeap = new PriorityQueue<>();
    }

    public void addNum(int num) {
        maxHeap.offer(num); // add number to max heap

        minHeap.offer(maxHeap.poll()); // rebalance heaps

        if (maxHeap.size() < minHeap.size()) {
            maxHeap.offer(minHeap.poll()); // ensure maxHeap has the same size as or one more element than minHeap
        }
    }

    public double findMedian() {
        if (maxHeap.size() > minHeap.size()) {
            return maxHeap.peek(); // if max heap has more elements, then median is top of max heap
        } else {
            return (maxHeap.peek() + minHeap.peek()) / 2.0; // otherwise, average top of min and max heap
        }
    }

    public static void main(String[] args) {
        MedianHeap mh = new MedianHeap();

        mh.addNum(-10);
        mh.addNum(4);
        mh.addNum(6);
        mh.addNum(1000);
        mh.addNum(10);
        mh.addNum(20);

        System.out.println(mh.findMedian()); // prints: 15.0
    }
}
```

