[{"role": "assistant", "content": "Here's a Java implementation of Quicksort algorithm utilizing median-of-three function:

```java
public class QuickSort {

    static void quicksort(int arr[], int low, int high) {
        if (low < high) {

            // Finding pivot element such that 
            // elements smaller than pivot are on the left 
            // and elements greater than pivot are on right
            int pivot = partition(arr, low, high);

            // Recursive call for elements on the left of pivot
            quicksort(arr, low, pivot - 1);

            // Recursive call for elements on the right of pivot
            quicksort(arr, pivot + 1, high);
        }
    }

    static int partition(int arr[], int low, int high) {
        // Median of three for pivot
        int mid = low + (high - low) / 2;
        if (arr[low] > arr[mid])
            swap(arr, low, mid);
        if(arr[low] > arr[high])
            swap(arr, low, high);
        if(arr[mid] > arr[high])
            swap(arr, mid, high);

        int pivot = arr[mid];
        swap(arr, mid, high);
        int i = (low - 1);

        for(int j = low; j <= high; j++)
        {
            // Check if current element is smaller than pivot
            if(arr[j] < pivot)
            {
                i++;
                swap(arr, i, j);
            }
        }

        // swapping element at i+1 and high
        swap(arr, i + 1, high);

        // return position of pivot
        return (i + 1);
    }

    static void swap(int arr[], int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    static void printArray(int array[]) {
        for(int i: array) {
            System.out.print(i + " ");
        }
    }

    public static void main(String args[]) {
        int array[] = {10, 7, 8, 9, 1, 5};
        quicksort(array, 0, array.length - 1);
        printArray(array);
    }
}
```

