```java
import java.util.*;
import java.lang.*;

class Solution {
    /**
    Given an array arr of integers, find the minimum number of transformations required to make the array a palindrome. 
    A palindromic array is one that reads the same forwards and backwards. 
    One transformation consists of incrementing or decrementing an integer by 1. Once an integer reaches its target value,
    it can't be changed again. Negative integers are allowed.

    For example:
    smallestChange(Arrays.asList(1,2,3,5,4,7,9,6)) == 20 //(1,2,3,6,5,4,3,2)
    smallestChange(Arrays.asList(1, 2, 3, 4, 3, 2, 2)) == 2 // (1, 2, 3, 3, 3, 2, 1)
    smallestChange(Arrays.asList(1, 2, 3, 2, 1)) == 0
     */
    public int smallestChange(List<Integer> arr) {
        int changes = 0;

        int i = 0, j = arr.size() - 1;
        while (i <= j) {
            if (arr.get(i) != arr.get(j)) {
                changes += Math.abs(arr.get(i) - arr.get(j));
            }
            i++;
            j--;
        }

        return changes;
    }
}
```

