            hasUppercase = true;
        } else if (Character.isLowerCase(ch)) {
            hasLowercase = true;
        } else if (Character.isDigit(ch)) {
            hasDigit = true;
        } else if ("!@#$%^&*".indexOf(ch) != -1) {
