import java.util.HashMap;
import java.util.Map;

class LRUCache {
    private int capacity;
    private Map<Integer, String> cache;
    private Map<Integer, Integer> queryCount;

    public LRUCache(int capacity) {
        this.capacity = capacity;
        this.cache = new HashMap<>();
        this.queryCount = new HashMap<>();
    }

    public String get(int key) {
        if (cache.containsKey(key)) {
            int count = queryCount.getOrDefault(key, 0) + 1;
            queryCount.put(key, count);
            if (count > 3) { // Assuming the threshold for query count is 3
                return "ROLLBACK_MESSAGE";
            }
            return cache.get(key);
        }
        return "UNKNOWN";
    }

    public void put(int key, String value) {
        if (cache.size() >= capacity) {
            int lruKey = queryCount.entrySet().stream().min(Map.Entry.comparingByValue()).get().getKey();
            cache.remove(lruKey);
            queryCount.remove(lruKey);
        }
        cache.put(key, value);
        queryCount.put(key, 0);
    }
}
```

The `LRUCache` class maintains a map `cache` to store the key-value pairs, a map `queryCount` to track the number of times each key is queried, and the `capacity` to limit the maximum number of key-value pairs in the cache. The `get` method checks if the key exists in the cache and returns the value, "UNKNOWN" if the key is not present, or "ROLLBACK_MESSAGE" if the query count exceeds the threshold. The `put` method adds the key-value pair to the cache and evicts the least recently used pair if the cache is at its maximum capacity."}]

