    public Order createOrder(ShoppingCart shoppingCart, User user, ShippingAddress shippingAddress) {
        double subtotal = calculateSubtotal(shoppingCart);
        double tax = taxCalculator.calculateTax(subtotal, user.getLocation());
        double shippingCost = shippingCalculator.calculateShippingCost(subtotal, shippingAddress);

        double totalCost = subtotal + tax + shippingCost;

        Order order = new Order();
        order.setItems(shoppingCart.getItems());
        order.setTotalCost(totalCost);
        order.setShippingAddress(shippingAddress);

        return order;
    }

    private double calculateSubtotal(ShoppingCart shoppingCart) {
