import com.github.programmerr47.singleinstances.InstanceStorage.HierarchyLink;

public class HierarchyUtil {
    public static HierarchyLink findHierarchyLink(Class<?> class1, Class<?> class2) {
        if (class1.isAssignableFrom(class2)) {
            return new HierarchyLink(class1, class2);
        } else if (class2.isAssignableFrom(class1)) {
            return new HierarchyLink(class2, class1);
        } else {
            Class<?> commonAncestor = findCommonAncestor(class1, class2);
            if (commonAncestor != null) {
                return new HierarchyLink(commonAncestor, class1);
            }
        }
        return null;
    }

    private static Class<?> findCommonAncestor(Class<?> class1, Class<?> class2) {
        Class<?> current = class1;
        while (current != null) {
            Class<?> ancestor = class2;
            while (ancestor != null) {
                if (current.isAssignableFrom(ancestor)) {
                    return current;
                }
                ancestor = ancestor.getSuperclass();
            }
            current = current.getSuperclass();
        }
        return null;
    }
