    board[i][j] = ' '; // Mark the cell as visited
    boolean found = dfs(board, i + 1, j, word, index + 1) ||
                    dfs(board, i - 1, j, word, index + 1) ||
                    dfs(board, i, j + 1, word, index + 1) ||
                    dfs(board, i, j - 1, word, index + 1);
    board[i][j] = temp; // Restore the cell
    return found;
