    public static int countWordOccurrences(StringTokenizer tokenizer, String word) {
        int count = 0;
        while (tokenizer.hasMoreTokens()) {
            if (tokenizer.nextToken().equalsIgnoreCase(word)) {
                count++;
            }
        }
        return count;
    }
}
