    for (String caseBlock : cases) {
        String[] caseParts = caseBlock.split("\\}");
        String value = caseParts[0].trim();
        String code = caseParts[1].trim();
        if (value.equals("_") || Integer.parseInt(value) == expression) {
            return code;
        }
    }
    return "No match";
}
