import java.util.Spliterator;
import java.util.function.Consumer;

class DepthFirstSpliterator<T> implements Spliterator<T> {
    private DAGNode<T> currentNode;
    private List<DAGNode<T>> children;
    private int index;

    public DepthFirstSpliterator(DAGNode<T> node) {
        this.currentNode = node;
        this.children = new ArrayList<>(node.getChildren());
        this.index = 0;
    }

    @Override
    public boolean tryAdvance(Consumer<? super T> action) {
        if (index < children.size()) {
            action.accept(children.get(index).getValue());
            DepthFirstSpliterator<T> childSpliterator = new DepthFirstSpliterator<>(children.get(index));
            index++;
            return childSpliterator.tryAdvance(action);
        }
        return false;
    }

    @Override
    public Spliterator<T> trySplit() {
        if (index < children.size()) {
            int splitIndex = (index + children.size()) / 2;
            List<DAGNode<T>> splitChildren = children.subList(index, splitIndex);
            index = splitIndex;
            return new DepthFirstSpliterator<>(splitChildren.get(0));
        }
        return null;
    }

    @Override
    public long estimateSize() {
        return children.size() - index;
    }

    @Override
    public int characteristics() {
        return Spliterator.DISTINCT | Spliterator.ORDERED | Spliterator.SIZED | Spliterator.SUBSIZED | Spliterator.NONNULL;
    }
}
