import java.util.*;

public class DocumentationResolver {
    public static List<String> resolveInheritDoc(List<String> documentation) {
        Map<String, String> methodDocs = new HashMap<>();
        List<String> resolvedDocs = new ArrayList<>();

        for (String doc : documentation) {
            if (doc.contains("@inheritdoc")) {
                String[] parts = doc.split("\\s+");
                String methodName = parts[parts.length - 1];
                String inheritedDoc = methodDocs.get(methodName);
                if (inheritedDoc != null) {
                    String resolvedDoc = doc.replace("@inheritdoc " + methodName, inheritedDoc);
                    resolvedDocs.add(resolvedDoc);
                } else {
                    resolvedDocs.add(doc); // If method documentation not found, keep the original
                }
            } else {
                resolvedDocs.add(doc);
                if (doc.startsWith("/**")) {
                    String methodName = extractMethodName(doc);
                    methodDocs.put(methodName, doc);
                }
            }
        }

        return resolvedDocs;
    }

    private static String extractMethodName(String doc) {
        String[] lines = doc.split("\n");
        for (String line : lines) {
            if (line.contains("*/")) {
                continue;
            }
            if (line.contains("@inheritdoc")) {
                String[] parts = line.split("\\s+");
                return parts[parts.length - 1];
            }
        }
        return "";
    }

    public static void main(String[] args) {
        List<String> documentation = Arrays.asList(
                "/**",
                " * This is the base method.",
                " */",
                "/**",
                " * Description of the overridden method.",
                " * @inheritdoc baseMethod",
                " */",
                "/**",
                " * Another method with no inheritance.",
                " */"
        );

        List<String> resolvedDocumentation = resolveInheritDoc(documentation);
        for (String doc : resolvedDocumentation) {
            System.out.println(doc);
        }
    }
}
